(()=>{'use strict';const pieces=JSON.parse(document.getElementById('pieces').textContent),dialog=document.getElementById('post-dialog'),zoom=document.getElementById('zoom-dialog');let opener,index=0,current,touchX=0;const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const showZoom=(url,alt='')=>{zoom.querySelector('img').src=url;zoom.querySelector('img').alt=alt;zoom.showModal()};
function paint(){const s=current.slides[index],stage=dialog.querySelector('.slide-stage');if(!stage)return;stage.innerHTML=s.image?'<img src="'+s.image+'" alt="'+esc(s.alt)+'">':'<div class="idea-slide">'+Object.entries(s.card).map(([k,v])=>'<h4>'+esc(k)+'</h4><p>'+esc(v)+'</p>').join('')+'</div>';dialog.querySelector('.slide-count').textContent=(index+1)+' / '+current.slides.length;dialog.querySelector('[data-prev]').disabled=index===0;dialog.querySelector('[data-next]').disabled=index===current.slides.length-1;stage.querySelector('img')?.addEventListener('click',()=>showZoom(s.image,s.alt))}
function move(n){if(!current)return;const next=Math.max(0,Math.min(current.slides.length-1,index+n));if(next===index)return;index=next;paint();if(!matchMedia('(prefers-reduced-motion:reduce)').matches)dialog.querySelector('.slide-stage').animate([{opacity:.65,transform:'translateX('+(n>0?-18:18)+'px)'},{opacity:1,transform:'translateX(0)'}],{duration:300,easing:'cubic-bezier(.2,.7,.2,1)'});}
function disclosures(body){
 const box=document.createElement('div');box.innerHTML=body;const story=box.querySelector('.story');if(story)story.remove();
 const groups=[];let group={title:'الفكرة والرسالة والجمهور والهدف',html:''};
 for(const child of [...box.children]){if(child.tagName==='H3'){if(group.html)groups.push(group);group={title:child.textContent,html:''};}else group.html+=child.outerHTML;}
 if(group.html)groups.push(group);
 return groups.map(g=>'<details class="piece-detail"><summary>'+esc(g.title)+'</summary>'+g.html+'</details>').join('')+(story?story.outerHTML:'');
}
document.querySelectorAll('[data-piece]').forEach(b=>b.addEventListener('click',()=>{
 opener=b;current=pieces.find(p=>p.id===b.dataset.piece);index=0;
 const gallery=current.slides.length?'<div class="gallery" aria-label="صور القطعة"><div class="slide-stage"></div><div class="slider-controls"><button data-prev aria-label="الصورة السابقة">←</button><span class="slide-count" aria-live="polite"></span><button data-next aria-label="الصورة التالية">→</button></div></div>':'<div class="reel-cover"><img src="/agri/assets/two-weeks/reel-'+({'piece-3':'01','piece-6':'02','piece-8':'03'}[current.id])+'-cover.svg" alt="'+esc(current.title)+'"></div>';
 document.getElementById('post-content').innerHTML='<div class="modal-title"><small>'+esc(current.kind)+'</small><h2>'+esc(current.title)+'</h2></div><div class="modal-layout">'+gallery+'<div class="modal-copy"><p class="piece-intro">'+esc(current.fields['الفكرة'])+'</p>'+disclosures(current.body)+'<details class="piece-detail"><summary>الكابشن · العربية وEnglish</summary><div class="caption">'+current.caption+'</div></details></div></div>';
 dialog.showModal();dialog.scrollTop=0;
 dialog.querySelector('[data-prev]')?.addEventListener('click',()=>move(-1));dialog.querySelector('[data-next]')?.addEventListener('click',()=>move(1));
 dialog.querySelectorAll('[data-zoom]').forEach(el=>el.addEventListener('click',()=>showZoom(el.dataset.zoom,el.querySelector('img').alt)));
 dialog.querySelector('.gallery')?.addEventListener('touchstart',e=>{touchX=e.changedTouches[0].clientX},{passive:true});dialog.querySelector('.gallery')?.addEventListener('touchend',e=>{const d=e.changedTouches[0].clientX-touchX;if(Math.abs(d)>45)move(d>0?1:-1)},{passive:true});if(current.slides.length)paint();
}));
for(const d of [dialog,zoom]){d.querySelector('.close').addEventListener('click',()=>d.close());d.addEventListener('click',e=>{if(e.target===d)d.close()})}dialog.addEventListener('close',()=>{opener?.focus({preventScroll:true});current=null});
function week(n){document.querySelectorAll('[data-week]').forEach(b=>{const yes=b.dataset.week===String(n);b.setAttribute('aria-selected',String(yes));b.tabIndex=yes?0:-1});for(const i of [1,2])document.getElementById('week'+i).hidden=i!==Number(n)}document.querySelectorAll('[data-week]').forEach(b=>{b.addEventListener('click',()=>week(b.dataset.week));b.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const n=e.key==='Home'?1:e.key==='End'?2:b.dataset.week==='1'?2:1;week(n);document.getElementById('tab'+n).focus()}})});
const aliases={intro:'home',review:'start',idea:'start',plan:'start',content:'samples','execution-samples':'samples',together:'pricing'};function route(){const id=location.hash.slice(1);if(aliases[id]){history.replaceState(null,'','#'+aliases[id]);document.getElementById(aliases[id]).scrollIntoView()}else if(!id){history.replaceState(null,'','#home');scrollTo(0,0)}}history.scrollRestoration='manual';addEventListener('pageshow',route);addEventListener('hashchange',route);
dialog.addEventListener('keydown',e=>{if(zoom.open||!current?.slides.length)return;if(e.key==='ArrowRight'){e.preventDefault();move(1)}else if(e.key==='ArrowLeft'){e.preventDefault();move(-1)}});
document.querySelectorAll('.card-rail').forEach(rail=>{
 const next=document.querySelector('[data-rail-next="'+rail.id+'"]'),prev=document.querySelector('[data-rail-prev="'+rail.id+'"]'),status=document.querySelector('[data-rail-status="'+rail.id+'"]');
 const step=()=>rail.children[0].getBoundingClientRect().width+16;
 const update=()=>{const pos=Math.round(Math.abs(rail.scrollLeft)/step());status.textContent=(pos+1)+' / '+rail.children.length;prev.disabled=Math.abs(rail.scrollLeft)<3;next.disabled=Math.abs(rail.scrollLeft)>=rail.scrollWidth-rail.clientWidth-3;};
 const moveRail=n=>rail.scrollBy({left:-n*step(),behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth'});
 next.addEventListener('click',()=>moveRail(1));prev.addEventListener('click',()=>moveRail(-1));rail.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();moveRail(e.key==='ArrowRight'?1:-1)}});
 let frame=0;rail.addEventListener('scroll',()=>{if(!frame)frame=requestAnimationFrame(()=>{frame=0;update()})},{passive:true});addEventListener('resize',update);update();
});
const reduced=matchMedia('(prefers-reduced-motion:reduce)');if(!reduced.matches&&'IntersectionObserver'in window){const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){io.unobserve(e.target);e.target.animate([{opacity:.7,transform:'translateY(14px)'},{opacity:1,transform:'none'}],{duration:430,easing:'cubic-bezier(.2,.7,.2,1)'})}}),{threshold:.08});document.querySelectorAll('.section-title,.brief-grid article,.post,.plan').forEach(e=>io.observe(e))}
})();
